  AND sq = #{ sq }

mapper.update:
UPDATE t_file
SET description = #{ description }
WHERE filekey = #{ filekey }
  AND sq = #{ sq }

mapper.select:
SELECT description
FROM t_file
WHERE sq = #{ sq }

SELECT *
FROM t_file
WHERE sq = #{ sq }
 AND filekey = #{ filekey }

SELECT *
FROM t_file
